vector<int> parent(n, -1), order{0};
for (int i = 0; i < n; ++i) {
    int u = order[i];
    for (int v : g[u]) {
        if (v == parent[u]) continue;
        parent[v] = u;
        order.push_back(v);
    }
}

vector<ll> sub(n, 1);
ll ans = 0;
for (int i = n - 1; i > 0; --i) {
    int u = order[i];
    ans += sub[u] * (n - sub[u]);
    sub[parent[u]] += sub[u];
}
cout << ans << '\n';

